// Build the GPT-4o vision request for the utility bill image
const img = $json.img_url ? $json.img_url : ('data:image/png;base64,' + $json.img_b64);
const system = "You are a utility billing assistant for a small landlord or property manager. The user forwards a photo, scan or screenshot of a utility bill (electricity, water, gas or combined) for a property where several units share one meter. Read the bill and extract the key fields. Respond with ONLY valid JSON in this exact shape: {\"provider\": string, \"utility\": string (\"electricity\", \"water\", \"gas\" or \"combined\"), \"period\": string, \"bill_date\": string or null, \"due_date\": string or null, \"total_amount\": number, \"currency\": string, \"address\": string or null, \"meter_number\": string or null, \"opening_reading\": number or null, \"closing_reading\": number or null, \"summary\": string, \"confidence\": number between 0 and 1}. If the image is not a readable utility bill, set provider to \"unreadable\" and confidence to 0.";
const userText = 'Landlord note from the forward: ' + ($json.note || 'none') + '.';
return [{ json: { reqObj: {
  model: 'gpt-4o', temperature: 0.1, max_tokens: 1000,
  messages: [
    { role: 'system', content: system },
    { role: 'user', content: [ { type: 'text', text: userText }, { type: 'image_url', image_url: { url: img } } ] }
  ]
} } }];

// Parse the GPT-4o vision JSON out of the OpenAI-compatible response
let raw = '';
try {
  const choices = $json.choices;
  raw = (choices && choices[0] && choices[0].message && choices[0].message.content) || '';
} catch (e) { raw = ''; }
raw = (raw || '').trim();
if (raw.startsWith('```')) {
  raw = raw.replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
}
let p;
try {
  p = JSON.parse(raw);
} catch (e) {
  p = { provider: 'unreadable', utility: 'combined', summary: 'Could not parse model output', confidence: 0,
        period: null, bill_date: null, due_date: null, total_amount: null, currency: 'USD',
        address: null, meter_number: null, opening_reading: null, closing_reading: null };
}
return [{
  json: {
    bill_id: $('Normalize forwarded bill').item.json.bill_id,
    received_at: $('Normalize forwarded bill').item.json.received_at,
    submitter: $('Normalize forwarded bill').item.json.submitter,
    note: $('Normalize forwarded bill').item.json.note,
    img_url: $('Normalize forwarded bill').item.json.img_url,
    img_present: $('Normalize forwarded bill').item.json.img_present,
    provider: p.provider || 'unreadable',
    utility: p.utility || 'combined',
    period: p.period || '',
    bill_date: p.bill_date || null,
    due_date: p.due_date || null,
    total_amount: p.total_amount ?? null,
    currency: p.currency || 'USD',
    address: p.address || null,
    meter_number: p.meter_number || null,
    opening_reading: p.opening_reading ?? null,
    closing_reading: p.closing_reading ?? null,
    summary: p.summary || '',
    confidence: p.confidence ?? 0
  }
}];

// Deterministic split: proportional to occupancy weights, no AI arithmetic.
// Tenants come from the roster read (this node's input), bill fields from Parse bill fields.
const t = $input.all().map(i => i.json);
const P = $('Parse bill fields').item.json;
const total = Number(P.total_amount);
const currency = P.currency || 'USD';
const weightSum = t.reduce((s, x) => s + Number(x.occupancy_weight || 1), 0);
const raw = t.map(x => ({ unit: x.unit, tenant_name: x.tenant_name, email: x.email,
  weight: Number(x.occupancy_weight || 1), share: total * (Number(x.occupancy_weight || 1) / weightSum) }));
let assigned = 0;
raw.forEach(x => x.amount = Math.round(x.share * 100) / 100);
raw.sort((a, b) => b.weight - a.weight || b.share - a.share);
assigned = raw.reduce((s, x) => s + x.amount, 0);
let drift = Math.round((total - assigned) * 100) / 100;
if (raw.length) raw[0].amount = Math.round((raw[0].amount + drift) * 100) / 100;
const lines = raw.map(x => `${x.unit} (${x.tenant_name}): ${currency} ${x.amount.toFixed(2)}`).join('\n');
return [{ json: {
  bill_id: P.bill_id, provider: P.provider, utility: P.utility, period: P.period,
  due_date: P.due_date, total_amount: total, currency: currency, address: P.address,
  split_text: lines,
  unit_count: raw.length,
  splits: raw,
  splitsJson: JSON.stringify(raw.map(x => ({ reading_id: P.bill_id + '-' + x.unit, bill_id: P.bill_id, unit: x.unit, utility: P.utility, weight: x.weight })))
} }];

// Fan out: one item per tenant with fields the Gmail node can map directly
const C = $('Compute unit shares').first().json;
return C.splits.map(s => ({ json: {
  email: s.email, tenant_name: s.tenant_name, unit: s.unit, amount: s.amount,
  utility: C.utility, period: C.period, total_amount: C.total_amount,
  currency: C.currency, address: C.address, due_date: C.due_date, bill_id: C.bill_id
} }));

// Summarize open bills from earlier days for the morning sweep
const rows = $json.rows || $input.all().map(i => i.json);
if (!rows.length) {
  return [{ json: { any_open: false, text: 'All clear: every forwarded utility bill has been processed.', count: 0 } }];
}
const lines = rows.map(r => `${r.bill_id} | ${r.provider} | ${r.utility} | ${r.period} | ${r.total_amount} ${r.currency} | ${r.status} | received ${String(r.received_at).slice(0,16)}`);
return [{ json: {
  any_open: true, count: rows.length,
  text: 'Open utility bills from earlier days (' + rows.length + '):\n' + lines.join('\n')
} }];
